public enum Error: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case IoError(message: String)
    
    case ReqwestError(message: String)
    
    case ProstDecodeError(message: String)
    
    case ProstEncodeError(message: String)
    
    case ResponseDataMissing(message: String)
    
    case CacheSerdeError(message: String)
    
    case Uninitialized(message: String)
    
    case UnknownError(message: String)
    
    case HttpError(message: String)
    
    case UnAuthorized(message: String)
    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension Error: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeError: FfiConverterRustBuffer {
    typealias SwiftType = Error

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Error {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .IoError(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .ReqwestError(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .ProstDecodeError(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .ProstEncodeError(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .ResponseDataMissing(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .CacheSerdeError(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .Uninitialized(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 8: return .UnknownError(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 9: return .HttpError(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 10: return .UnAuthorized(
            message: try FfiConverterString.read(from: &buf)
        )
        

        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: Error, into buf: inout [UInt8]) {
        switch value {

        

        
        case .IoError(_ /* message is ignored*/):
            writeInt(&buf, Int32(1))
        case .ReqwestError(_ /* message is ignored*/):
            writeInt(&buf, Int32(2))
