#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeTargetType: FfiConverterRustBuffer {
    typealias SwiftType = TargetType

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> TargetType {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .post(postId: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 2: return .comment(commentId: try FfiConverterUInt64.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: TargetType, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .post(postId):
            writeInt(&buf, Int32(1))
            FfiConverterUInt64.write(postId, into: &buf)
            
        
        case let .comment(commentId):
            writeInt(&buf, Int32(2))
            FfiConverterUInt64.write(commentId, into: &buf)
            
        }
    }
}


